const numbers = [1, 2, 3, 4];
const squares = numbers.map(function (n) { return n * n; });
const squaresArrow = numbers.map((n) => n * n);
console.log(squares.join(", "));
console.log(squaresArrow.join(", "));

const makeUser = (name, role = "member") => ({ name, role });   // parentheses return an object
console.log(JSON.stringify(makeUser("Ada")));

const timer = {
  seconds: 0,
  start() {
    const tick = () => this.seconds++;   // arrow keeps the object's this
    tick();
    tick();
    return this.seconds;
  },
};
console.log(timer.start());

const point = [10, 20, 30];
const [x, y] = point;
console.log(x + y);

const [first, , third] = point;      // skip the second element
console.log(first + third);

const user = { name: "Grace", age: 85, country: "US" };
const { name, country: nation, email = "none" } = user;
console.log(`${name} from ${nation}, email: ${email}`);

function describe({ name, age }) {
  return `${name} is ${age}`;
}
console.log(describe(user));

let a = 1;
let b = 2;
[a, b] = [b, a];                      // swap without a temporary variable
