const config = { retries: 0, logger: null };
console.log(config.retries ?? 3);
console.log(config.retries || 3);           // 0 is falsy, so || replaces it
console.log(config.logger?.level ?? "info");
console.log(config.onError?.());             // calling a missing function safely
console.log(config.tags?.[0] ?? "no tags");

